输出是否为素数。
#include <math.h>
#include <stdio.h>
int IsPrimeNumber(int number)
{ int i;
if (number <= 1)
return 0;
for (i=2; i<sqrt(number); i++)
{     if ((number % i) == 0)
return 0; }
return 1;}
